// A suggestion is based on the episode the player described, never on the unrelated daily plan.
export function episodeDrill(note,answer=''){
 const text=String(note||'').toLowerCase();
 const cause=String(answer||'').toLowerCase();
 if(/хг|high.?ground|хайграунд|высот/.test(text)){
  if(/сбил|скинул|сброс|прострел|сломал|сломали|застрел/.test(cause))return {
   title:'Проверь, как удерживал ХГ',
   action:'В следующем похожем лейте перед удержанием ХГ проверь, на чём держится твоя позиция и откуда её могут сбить. При потере опоры сразу переходи на заранее выбранный безопасный леер.',
   measure:'В двух похожих ситуациях запиши, кто и откуда выбил опору, какой леер выбрал после потери ХГ и сохранил ли контроль.'
  };
  if(/разбил|упал|паден|прыгнул|не долетел|не успел постро|не поставил/.test(cause))return {
   title:'Проверь путь спуска с ХГ',
   action:'Перед следующим спуском с ХГ назови точку приземления и безопасный леер; спускайся только после проверки опоры и возможности построиться.',
   measure:'В двух похожих спусках запиши, где была опора, куда приземлился и получил ли урон от падения.'
  };
  return {
   title:'Сначала выясни, как потерял ХГ',
   action:'Пересмотри момент потери ХГ: тебя сбили с позиции или ты сорвался при спуске? Проверь опору, источник урона и выбранный путь вниз. После этого выбери упражнение под подтверждённую причину.',
   measure:'Запиши факт: источник потери ХГ, положение опоры и безопасный леер, который был доступен.'
  };
 }
 if(/лейт|late|эндгейм|endgame|хг|high.?ground|высот/.test(text))return {
  title:'Проверь решение в поздней стадии',
  action:'В следующем похожем лейте перед выходом из укрытия проверь безопасный путь, запас ресурсов и позицию ближайшего соперника. Назови причину выхода до действия.',
  measure:'Запиши в двух похожих ситуациях: что было известно перед выходом, какое решение принял и чем оно закончилось.'
 };
 if(/зон|ротац|маршрут|rotate|storm/.test(text))return {
  title:'Проверь выбор маршрута',
  action:'Перед следующей ротацией сравни два пути и выбери один по укрытию, времени и доступным ресурсам. Назови условие, при котором переключишься на запасной.',
  measure:'Запиши две ротации: выбранный путь, известный риск, момент изменения плана и результат.'
 };
 if(/лэнд|ленд|лок|спавн|контест|loot|лут|дроп/.test(text))return {
  title:'Проверь первые решения после высадки',
  action:'В следующем похожем старте перед первым контактом проверь оружие, щиты, укрытие и положение соперника. Если данных не хватает, выбери безопасный способ получить информацию.',
  measure:'Запиши в двух стартах: что было известно до контакта, какое решение принял и что произошло после него.'
 };
 if(/тиммейт|напарник|колл|команд|дуо|трио|состав/.test(text))return {
  title:'Проверь совместное решение',
  action:'Перед следующим совместным заходом коротко назови цель и дождись подтверждения напарника. Если готовности нет, не начинай размен в одиночку.',
  measure:'В двух похожих моментах запиши колл, ответ напарника, синхронность действий и результат.'
 };
 if(/файт|fight|размен|урон|пик|пуш|противник|соперник|убил|умер/.test(text))return {
  title:'Проверь решение перед контактом',
  action:'Перед следующим похожим файтом назови своё преимущество, риск и путь выхода. Начинай размен только если можешь объяснить, зачем он нужен.',
  measure:'В двух контактах запиши HP, укрытие, известную информацию, решение и результат.'
 };
 return {
  title:'Сначала уточни эпизод',
  action:'Выбери одно решение из описанного момента и проверь его в следующей похожей ситуации. Перед действием назови известные факты и одну неопределённость.',
  measure:'Запиши две похожие ситуации: факты до решения, действие и наблюдаемый результат.'
 };
}
